SELECT * FROM afv_canvas_node_run WHERE id = #{id} AND run_id = #{runId} AND owner_instance_id = #{owner} AND owner_epoch = #{epoch}
    AND lease_until > UTC_TIMESTAMP(6) AND (status IN ('READY','RUNNING','CANCEL_REQUESTED','NEEDS_REVIEW','UNKNOWN_SUBMISSION')
        OR (status='WAITING_CONFIRMATION' AND external_kind='AGENT')) FOR UPDATE
